--region public
---RefreshUI
---@param equipDojo EquipDojo
---@param index number
---@param unlockTipText string 解锁提示文字
function CardProgressionEquipmentInfoAttrNode:RefreshUI(equipDojo, index, unlockTipText)
    local key = string.format("attr%sId", index)
    local attrAdditionId = checkNumber(equipDojo[key])
    if checkNumber(attrAdditionId) == 0 then return end
    
    local isOwnAttr = checkInt(equipDojo.star) >= index
    
    CfUtils.SetActive(self.LockGroup, not isOwnAttr)
    key = string.format("attr%sNum", index)
    local attrNum = equipDojo[key]
    local qKay = string.format("attr%sQuality", index)
    local attrQuality = checkInt(equipDojo[qKay])
    self:RefreshAttrNode(attrAdditionId, attrNum, attrQuality)
    EquipUtils.SwitchSubAttrColorByQuality(self.ImgBgRare, attrQuality)
    local percent = EquipUtils.GetSubAttrPercent(equipDojo.equipmentId, attrAdditionId, attrNum)
    self.Slider.value = percent
    CfUtils.SetUISwitchImage(self.ImgPointRare, attrQuality)
    CfUtils.FillText(self.TxtSerialNumber, index)
end
--endregion public

--region private
function CardProgressionEquipmentInfoAttrNode:RefreshAttrNode(attrAdditionId, attrNum, attrQuality)
    ---@type BasicAttrAdditionVo
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(attrAdditionId) or {}
    self.AttrNameText.text = attrAdditionVo.attrAdditionName
    self.AttrNumText.text = attribute_format(attrAdditionVo.isConversion, attrNum)
end
--endregion private

return CardProgressionEquipmentInfoAttrNode